import prettier from "prettier";
import { mergeImports } from "../src/mergeImports";

const template = `import { Construct } from "constructs";
import { App, TerraformStack } from "cdktn";

class MyStack extends TerraformStack {
  constructor(scope: Construct, id: string) {
    super(scope, id);
  }
}
`;

const generated = `import { Construct } from "constructs";
import { TerraformOutput, TerraformStack } from "cdktn";
/*
 * Provider bindings are generated by running \`cdktn get\`.
 * See https://cdktn.io/docs/concepts/providers#import-providers for more details.
 */
import { RandomProvider } from "./.gen/providers/random/provider";
import * as Test from "./.gen/modules/modules/test";
`;

describe("mergeImports", () => {
  it("drops generated imports the input file already has", () => {
    const merged = mergeImports(generated, template);

    expect(merged).not.toContain(`import { Construct } from "constructs";`);
    expect(merged).toContain(`import { TerraformOutput } from "cdktn";`);
    expect(merged).toContain(
      `import { RandomProvider } from "./.gen/providers/random/provider";`,
    );
    expect(merged).toContain(
      `import * as Test from "./.gen/modules/modules/test";`,
    );
    expect(merged).toContain("Provider bindings are generated");
  });

  it("declares every imported name once in the converted file", () => {
    const output = prettier.format(
      [mergeImports(generated, template), template].join("\n"),
      { parser: "babel-ts" },
    );

    const importedNames = [
      ...output.matchAll(/import\s+\{([^}]*)\}\s*from/g),
    ].flatMap(([, names]) => names.split(",").map((name) => name.trim()));

    expect(importedNames.sort()).toEqual([
      "App",
      "Construct",
      "RandomProvider",
      "TerraformOutput",
      "TerraformStack",
    ]);
  });

  it("keeps a name imported from a different module", () => {
    const merged = mergeImports(
      `import { Construct } from "./my-constructs";\n`,
      template,
    );

    expect(merged).toContain(`import { Construct } from "./my-constructs";`);
  });

  it("keeps aliased imports that differ from the input file", () => {
    const merged = mergeImports(
      `import { TerraformStack as Stack, TerraformStack } from "cdktn";\n`,
      template,
    );

    expect(merged).toContain(
      `import { TerraformStack as Stack } from "cdktn";`,
    );
  });

  it("returns generated imports unchanged when the input has no imports", () => {
    expect(mergeImports(generated, "const x = 1;\n")).toBe(generated);
  });
});
